/** 
 * Default value for a given property.
 * @param property The property to query.
 * @return A default value if any or null if not found.
 */
public String getDefault(String property){
  String value = null;
  try {
    value = defaults.get(property);
  } catch (ClassCastException e) {
    log.error(String.format("Invalid property type for key '%s'", property), e);
  } catch (NullPointerException e) {
    log.error(String.format("Null property key provided"), e);
  }
  if (null == value) {
    log.warn(String.format("No property with key '%s'", property));
  }
  return value;
}
